def solve(clue):
    g = [list(row) for row in clue.split()]
    for m in legal(g, 'o'):
        r, k, a, b = m
        h = [row[:] for row in g]
        h[a][b] = h[r][k]; h[r][k] = '.'
        if not legal(h, 'x'):
            return "%d,%d>%d,%d" % m
